class Solution {
public:
    vector<string> assignUmbrella(vector<int>& rain) {
        int n = rain.size();
        vector<string> ans(n);
        int cntA = 0, cntB = 0;
        for (int i = 0; i < n; ++i) {
            bool needBob = (rain[i] == 1);
            bool needAlice = (i + 1 < n && rain[i] == 1 && rain[i + 1] == 1);
            if (!needBob && !needAlice) {
                ans[i] = "None";
            } else if (needBob && !needAlice) {
                ans[i] = "Bob";
                ++cntB;
            } else if (!needBob && needAlice) {
                ans[i] = "Alice";
                ++cntA;
            } else { // both need it
                if (cntA <= cntB) {
                    ans[i] = "Alice";
                    ++cntA;
                } else {
                    ans[i] = "Bob";
                    ++cntB;
                }
            }
        }
        return ans;
    }
};
